'use strict'

const i18n = require( './i18n.min' )

// Polyfill: make electron-store work in renderer
try {
	const electron = require( 'electron' )
	const remote = require( '@electron/remote' )
	if( !electron.app ) electron.app = remote.app
} catch( e ) {}

const ipc = require( 'electron' ).ipcRenderer

const Store = require( 'electron-store' )
const store = new Store()
const $ = require( 'jquery' )
const jqueryI18next = require( 'jquery-i18next' )

jqueryI18next.init(i18n, $)

const fetch = require( './fetch.min' )
const entities = require( './entities.min' )

// Access the bookmarks data store (same as fetch.js uses)
let bookmarkStore = new Store({name: 'bookmarks'})



//note(dgmid): log exceptions

window.onerror = function( error, url, line ) {
	
	ipc.send( 'error-in-render', {error, url, line} )
}



//note(dgmid): set lang & localize strings

$('html').attr('lang', i18n.language)
$('header').localize()
$('button').localize()



//note(dgmid): close modal

function closeModal() {
	
	ipc.send( 'close-current-window' )
}



//note(dgmid): find duplicate bookmarks (same URL)

function findDuplicates() {
	
	let bookmarkData = bookmarkStore.get( 'data' )
	
	if( !bookmarkData || !Array.isArray( bookmarkData ) ) {
		
		$('#results').html( `<div class="summary">${i18n.t('findduplicates:error.nodata', 'No bookmark data available.')}</div>` )
		return
	}
	
	// Group bookmarks by URL
	let groups = {}
	
	for( let item of bookmarkData ) {
		
		let url = item.url
		
		if( !groups[url] ) groups[url] = []
		groups[url].push( item )
	}
	
	// Filter groups with 2+ bookmarks
	let duplicates = Object.values( groups ).filter( group => group.length > 1 )
	
	if( duplicates.length === 0 ) {
		
		$('#results').html( `<div class="summary">${i18n.t('findduplicates:summary.none', 'No duplicate bookmarks found.')}</div>` )
		return
	}
	
	let html = `<div class="summary">${i18n.t('findduplicates:summary.found', '{{count}} duplicate groups found.', {count: duplicates.length})}</div>`
	
	for( let group of duplicates ) {
		
		let url = group[0].url,
			folderList = store.get( 'folders' ) || []
		
		function getFolderName( id ) {
			
			if( id === -1 ) return 'Home'
			let f = folderList.find( x => x.id === id )
			return f ? f.text : '?'
		}
		
		html += `<div class="dup-group" data-url="${entities.encode(url)}">`
		html += `<button class="merge-btn" data-index="${duplicates.indexOf(group)}">${i18n.t('findduplicates:button.merge', 'Merge {{count}}', {count: group.length})}</button>`
		html += `<div class="dup-url">${entities.encode(url)}</div>`
		
		for( let item of group ) {
			
			let tags = (item.tags && item.tags.length) ? item.tags.join(', ') : '—',
				folders = (item.folders && item.folders.length) ? item.folders.map(getFolderName).join(', ') : 'Home'
			
			html += `<div class="dup-item" data-id="${item.id}">`
			html += `<span class="title">${entities.encode(item.title || '—')}</span>`
			html += `<div class="meta">${i18n.t('findduplicates:label.folders', 'Folders')}: ${entities.encode(folders)}</div>`
			html += `<div class="meta">${i18n.t('findduplicates:label.tags', 'Tags')}: ${entities.encode(tags)}</div>`
			html += `</div>`
		}
		
		html += `</div>`
	}
	
	$('#results').html( html )
}



//note(dgmid): merge duplicate bookmarks

function mergeGroup( groupIndex ) {
	
	let bookmarkData = bookmarkStore.get( 'data' )
	
	if( !bookmarkData ) return
	
	// Group by URL again
	let groups = {}
	for( let item of bookmarkData ) {
		if( !groups[item.url] ) groups[item.url] = []
		groups[item.url].push( item )
	}
	
	let duplicates = Object.values( groups ).filter( group => group.length > 1 )
	
	if( groupIndex >= duplicates.length ) return
	
	let group = duplicates[groupIndex],
		keep = group[0],
		toDelete = group.slice( 1 )
	
	// Combine all tags (unique)
	let allTags = []
	for( let item of group ) {
		
		for( let tag of (item.tags || []) ) {
			
			if( !allTags.includes( tag ) ) allTags.push( tag )
		}
	}
	
	// Combine all folders (unique)
	let allFolders = []
	for( let item of group ) {
		
		for( let f of (item.folders || []) ) {
			
			if( !allFolders.includes( f ) ) allFolders.push( f )
		}
	}
	
	// Build modify data for the kept bookmark
	let data = '?record_id=' + encodeURIComponent( keep.id )
	data += '&url=' + encodeURIComponent( keep.url )
	data += '&title=' + encodeURIComponent( keep.title || '' )
	data += '&description=' + encodeURIComponent( keep.description || '' )
	
	for( let tag of allTags ) {
		
		data += '&tags[]=' + encodeURIComponent( tag )
	}
	
	for( let f of allFolders ) {
		
		data += '&folders[]=' + encodeURIComponent( f )
	}
	
	// Keep a reference to the button
	let btn = $(`.merge-btn[data-index="${groupIndex}"]`)
	btn.prop( 'disabled', true ).text( i18n.t('findduplicates:button.merging', 'Merging…') )
	
	// First update the kept bookmark with combined data
	fetch.bookmarksApi( 'modify', keep.id, data, function() {
		
		// Then delete all duplicates
		let deleted = 0
		
		for( let item of toDelete ) {
			
			fetch.bookmarksApi( 'delete', item.id, '', function() {
				
				deleted++
				
				if( deleted === toDelete.length ) {
					
					// All deleted - refresh and close
					ipc.send( 'refresh', 'refresh' )
					closeModal()
				}
			})
		}
	})
}



$(document).ready(function() {
	
	$('#close').click( function() {
		
		closeModal()
	})
	
	// Event delegation for merge buttons
	$('#results').on( 'click', '.merge-btn', function() {
		
		let index = parseInt( $(this).data( 'index' ) )
		mergeGroup( index )
	})
	
	findDuplicates()
})

